import{_ as e,o as d,c as r,a4 as o}from"./chunks/framework.Dsbb2oA0.js";const m=JSON.parse('{"title":"CAD 图纸操作 · 入口指引","description":"","frontmatter":{},"headers":[],"relativePath":"zh/docs/9.AIManual/1.EntryGuide.md","filePath":"zh/docs/9.AIManual/1.EntryGuide.md"}'),a={name:"zh/docs/9.AIManual/1.EntryGuide.md"};function n(c,t,i,s,h,l){return d(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="cad-图纸操作-·-入口指引" tabindex="-1">CAD 图纸操作 · 入口指引 <a class="header-anchor" href="#cad-图纸操作-·-入口指引" aria-label="Permalink to &quot;CAD 图纸操作 · 入口指引&quot;">​</a></h1><p>涉及 CAD 图纸操作时，先判断操作侧，再读对应指南执行。</p><h2 id="路由规则" tabindex="-1">路由规则 <a class="header-anchor" href="#路由规则" aria-label="Permalink to &quot;路由规则&quot;">​</a></h2><table><thead><tr><th>用户意图</th><th>操作侧</th><th>指南</th></tr></thead><tbody><tr><td>网页中预览、浏览、编辑、绘制、标注、测量、图层管理、导出图纸</td><td>前端（mxcad）</td><td><a href="./2.FrontendMxCadGuide.html">前端 mxcad 指南</a></td></tr><tr><td>服务端处理图纸文件：格式转换、数据提取、参数化绘图生成、切分合并、批量导出</td><td>后端（MxServiceCode）</td><td><a href="./3.BackendMxServiceCodeGuide.html">后端 MxServiceCode 指南</a></td></tr><tr><td>SVG↔DWG 互转（svg 转 dwg / dwg 转 svg，mxcadassembly 不支持 SVG）</td><td>后端（mxcad-svg-dwg-kit 新套件）</td><td><a href="./4.BackendReferenceDocs/4.SvgDwgKitGuide.html">SVG⇄DWG 转换套件指南</a></td></tr><tr><td>两侧都涉及（如后台生成 DWG 后在网页预览）</td><td>先后端生成，再前端预览</td><td>依次读两份指南</td></tr></tbody></table><p><strong>用户未明确前端还是后端时，必须先询问，得到答复后再执行：</strong></p><blockquote><p>您这次是需要在<strong>网页中预览编辑</strong>图纸（前端 mxcad），还是通过<strong>后端服务</strong>处理图纸文件（如转换、生成、数据提取）？</p></blockquote><p>线索可辅助判断但不能替代询问：&quot;网页/浏览器/嵌入网站/mxcad/mxweb&quot; → 前端；&quot;服务端/Node/批量/生成图纸文件/数据提取/接口&quot; → 后端。</p><h2 id="文档链接与程序下载地址" tabindex="-1">文档链接与程序下载地址 <a class="header-anchor" href="#文档链接与程序下载地址" aria-label="Permalink to &quot;文档链接与程序下载地址&quot;">​</a></h2><h3 id="文档链接" tabindex="-1">文档链接 <a class="header-anchor" href="#文档链接" aria-label="Permalink to &quot;文档链接&quot;">​</a></h3><table><thead><tr><th>文档</th><th>链接</th></tr></thead><tbody><tr><td>入口指引（本文件）</td><td><a href="./1.EntryGuide.html">链接</a></td></tr><tr><td>前端 mxcad 指南</td><td><a href="./2.FrontendMxCadGuide.html">链接</a></td></tr><tr><td>后端 MxServiceCode 指南</td><td><a href="./3.BackendMxServiceCodeGuide.html">链接</a></td></tr><tr><td>MxServiceCode 命令参考</td><td><a href="./4.BackendReferenceDocs/1.MxServiceCodeCommandReference.html">链接</a></td></tr><tr><td>Mx2DNode 二开 API 参考</td><td><a href="./4.BackendReferenceDocs/2.Mx2DNodeSecondaryDevAPIReference.html">链接</a></td></tr><tr><td>部署与启动说明</td><td><a href="./4.BackendReferenceDocs/3.DeploymentAndStartup.html">链接</a></td></tr><tr><td>SVG⇄DWG 转换套件指南</td><td><a href="./4.BackendReferenceDocs/4.SvgDwgKitGuide.html">链接</a></td></tr></tbody></table><h3 id="程序下载地址" tabindex="-1">程序下载地址 <a class="header-anchor" href="#程序下载地址" aria-label="Permalink to &quot;程序下载地址&quot;">​</a></h3><p>两类包：<strong>单独转换程序</strong>（MxConvert，仅含 mxcadassembly）与<strong>后端服务</strong>（MxServiceCode，同时含后端服务和转换程序，即完整超集）。均为试用版（期限 6 个月），托管在外部站点（demo.mxdraw3d.com），直接按绝对地址下载。Linux 包基于 Ubuntu 20.04（<code>Ubuntu20</code>）构建，仅适用于 Ubuntu 20.04 x86_64 及以上兼容环境（如 Ubuntu 22.04）；ARM 机器（<code>uname -m</code> 为 <code>aarch64</code>）或更低版本系统请先停止并向用户确认。</p><table><thead><tr><th>程序</th><th>平台</th><th>下载地址</th></tr></thead><tbody><tr><td>单独转换程序 MxConvert（试用版）</td><td>Windows</td><td><a href="https://demo.mxdraw3d.com/download/MxConvert_TryVersion.zip" target="_blank" rel="noreferrer">MxConvert_TryVersion.zip</a></td></tr><tr><td>单独转换程序 MxConvert（试用版）</td><td>Linux（Ubuntu 20.04 x86_64）</td><td><a href="https://demo.mxdraw3d.com/download/MxConvert_Ubuntu20_TryVersion.zip" target="_blank" rel="noreferrer">MxConvert_Ubuntu20_TryVersion.zip</a></td></tr><tr><td>后端服务 MxServiceCode（含转换程序 mxcadassembly，试用版）</td><td>Windows</td><td><a href="https://demo.mxdraw3d.com/download/MxServiceCode_TryVersion.zip" target="_blank" rel="noreferrer">MxServiceCode_TryVersion.zip</a></td></tr><tr><td>后端服务 MxServiceCode（含转换程序 mxcadassembly，试用版）</td><td>Linux（Ubuntu 20.04 x86_64）</td><td><a href="https://demo.mxdraw3d.com/download/MxServiceCode_Ubuntu20_TryVersion.zip" target="_blank" rel="noreferrer">MxServiceCode_Ubuntu20_TryVersion.zip</a></td></tr><tr><td>SVG⇄DWG 转换套件 mxcad-svg-dwg-kit（纯 JS；启动器自动准备 node 与后端服务，缺服务时首次自动下载；含完整源码+构建工具）</td><td>全平台（纯 JS）</td><td><a href="https://demo.mxdraw3d.com/download/mxcad-svg-dwg-kit.zip" target="_blank" rel="noreferrer">mxcad-svg-dwg-kit.zip</a>（不可达时向用户询问）</td></tr></tbody></table><p><strong>固定临时路径（只下载一次，跨会话复用）</strong>：</p><ul><li>Windows：<code>%TEMP%\\MxCAD\\</code>（<code>%TEMP%</code> 为用户 Temp 目录环境变量，命令中直接使用，无需手动展开）</li><li>Linux：<code>/tmp/MxCAD/</code></li></ul><p><strong>程序排查与获取步骤</strong>（收到命令后执行）：</p><p><strong>第 1 步 判断任务需要什么</strong>：只需转换程序（格式转换 / PDF / 图片等 <code>mxcadassembly</code> 调用）或需要后端服务（命令调用 / 二开）。</p><p><strong>第 2 步 查看固定临时路径下有哪些东西</strong>，按下表处理：</p><table><thead><tr><th>临时目录现状</th><th>本次只需转换程序</th><th>本次需要后端服务</th></tr></thead><tbody><tr><td>什么都没有</td><td>按平台下载<strong>单独转换程序</strong>（MxConvert）zip，解压到临时路径</td><td>按平台下载<strong>后端服务</strong>（MxServiceCode）zip（含转换程序），解压到临时路径</td></tr><tr><td>只有转换程序（单独包解包，可能不在 <code>MxCAD\\Release\\</code> 下）</td><td>直接做试用版过期验证，通过即可用</td><td><strong>清空临时路径后下载解压后端服务 zip</strong></td></tr><tr><td>有后端服务（已解包，转换程序在 <code>MxCAD\\Release\\</code> / <code>Linux\\MxCAD\\</code>）</td><td>做试用版过期验证 + 包完整性验证，通过即用；<strong>不完整则清空后下载单独转换程序 zip 重下</strong></td><td>检查工程目录 <code>MxServiceCode\\MxServiceCode</code> 完整，完整即用；<strong>不完整则清空后下载后端服务 zip 重下</strong></td></tr></tbody></table><blockquote><p>注意各包目录结构固定：两个 zip 解压后都只有一个顶层目录（与 zip 同名：<code>MxConvert_TryVersion\\</code> / <code>MxServiceCode_TryVersion\\</code>）；单独转换程序包的转换程序文件（mxcadassembly.exe、fonts\\ 等）直接在该顶层目录里，后端服务包在该目录下含 <code>MxServiceCode\\</code> + <code>MxCAD\\Release\\</code>（Windows）/ <code>MxServiceCode\\</code> + <code>Linux\\MxCAD\\</code>（Linux）两个子目录。因此<strong>重新下载前必须先清空临时路径</strong>（后端包是完整超集，同时含后端与转换程序，清空重解不会丢东西）。系统清理临时目录后重新下载即可。不要扫描用户机器其他目录。</p></blockquote>',20)])])}const u=e(a,[["render",n]]);export{m as __pageData,u as default};
